package com.sunriseclock.sun_clock

import com.google.gson.JsonElement
import com.google.gson.JsonObject
import com.google.gson.JsonParser
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File
import java.time.Instant

/**
 * Checks the Kotlin port against test/solar_vectors.json, the same vectors
 * test/solar_vectors_test.dart checks lib/solar.dart and lib/sun_clock.dart
 * against (generated by tool/gen_solar_vectors.dart). The path comes from
 * app/build.gradle.kts.
 */
class SolarVectorsTest {
    private val timeToleranceMs = 5.0

    private fun cases(): List<JsonObject> {
        val path = System.getProperty("sunClock.solarVectors")
            ?: error("sunClock.solarVectors not set; run through Gradle")
        val root = JsonParser.parseString(File(path).readText()).asJsonObject
        return root.getAsJsonArray("cases").map { it.asJsonObject }
    }

    private fun JsonElement?.isNullish() = this == null || this.isJsonNull
    private fun ms(iso: String) = Instant.parse(iso).toEpochMilli()

    private fun assertTime(what: String, expected: JsonElement?, actual: Long?) {
        if (expected.isNullish()) {
            assertNull(what, actual)
            return
        }
        assertNotNull(what, actual)
        assertEquals(what, ms(expected!!.asString).toDouble(), actual!!.toDouble(), timeToleranceMs)
    }

    @Test
    fun fileCoversBothModes() {
        val c = cases()
        assertTrue(c.size >= 20)
        val modes = c.map { it.getAsJsonObject("sunClock")["mode"].asString }.toSet()
        assertEquals(setOf("normal", "fallback"), modes)
    }

    @Test
    fun matchesDartVectors() {
        for (c in cases()) {
            val name = c["name"].asString
            val now = ms(c["instant"].asString)
            val lat = c["lat"].asDouble
            val lon = c["lon"].asDouble

            val jd = SolarCalc.julianDay(now)
            assertEquals("$name julianDay", c["julianDay"].asDouble, jd, 1e-9)
            val (decl, eqTime) = SolarCalc.solarParams(jd)
            assertEquals("$name declination", c["declination"].asDouble, decl, 1e-9)
            assertEquals("$name equationOfTime", c["equationOfTime"].asDouble, eqTime, 1e-9)

            assertTime("$name sunrise", c["sunrise"], SolarCalc.sunEvent(now, lat, lon, rising = true))
            assertTime("$name sunset", c["sunset"], SolarCalc.sunEvent(now, lat, lon, rising = false))
            assertTime("$name solarNoon", c["solarNoon"], SolarCalc.solarNoon(now, lon))

            val s = c.getAsJsonObject("sunClock")
            val r = SunTime.read(now, SolarCalc.build(lat, lon, now, name))
            assertNotNull("$name reading", r)
            r!!
            val fallback = s["mode"].asString == "fallback"
            assertEquals("$name mode", fallback, r.realMinutesPerHour == null)
            assertEquals("$name isDay", s["isDay"].asBoolean, r.isDay)
            assertEquals("$name sunTime", s["sunTimeMs"].asDouble, r.sunMinutes * 60_000.0, timeToleranceMs)
            if (!fallback) {
                assertEquals(
                    "$name realMinutesPerSunHour",
                    s["realMinutesPerSunHour"].asDouble, r.realMinutesPerHour!!, 1e-4,
                )
            }
            assertTime("$name next", s["next"], r.next?.first)
            if (!s["nextIsSunrise"].isNullish()) {
                assertEquals("$name nextIsSunrise", s["nextIsSunrise"].asBoolean, r.next!!.second)
            }
        }
    }
}
